// GM-3DV2 R1：累积拾取法 method → 拾取槽序列（p=构造点 f=平面 c=圆柱面 e=边）；非累积法唔喺表内（走字段/按钮/遗留拾取）。
export const DATUM_CMD_ACC: Record<string, ('p' | 'f' | 'c' | 'e')[]> = {
  'plane:midplane': ['f', 'f'], 'plane:twoEdges': ['e', 'e'], 'plane:perp': ['f', 'e'], 'axis:cyl': ['c'],
  'point:twoEdges': ['e', 'e'], 'point:threePlanes': ['f', 'f', 'f'], 'point:edgePlane': ['e', 'f'], 'point:centerEdge': ['e'],
  'plane:threePoints': ['p', 'p', 'p'], 'axis:twoPoints': ['p', 'p'], 'point:midpoint': ['p', 'p'],
}
const _datumMethodLabel = (type: DatumCmdType, method: string) => DATUM_CMD_METHODS[type].find((m) => m.id === method)?.label ?? method
const _datumCmdDefaults = (type: DatumCmdType, method: string): Record<string, number | string> => {
  const key = type + ':' + method
  if (key === 'plane:offset') return { base: 'XY', offset: 30, angle: 0, aaxis: 'x' }
  if (key === 'plane:perp') return { dist: 0 }
  if (key === 'point:xyz') return { x: 0, y: 0, z: 0 }
  if (key === 'axis:dirPoint') return { dir: 'X', x: 0, y: 0, z: 0 }
  return {}
}
