let _fid = 0
const fid = () => 'F' + ++_fid
let _anSeq = 0
const anId = () => 'AN' + ++_anSeq   // GM-X1 #12：分析节点稳定 id
// GM-X1 #12：把一个分析 type 设为唯一可见（overlay 互斥），upsert 入节点表并隐藏其余。
function _soleVisibleAnalysis(arr: AnalysisNode[], type: AnalysisType, params?: Record<string, unknown>): AnalysisNode[] {
  const hidden = arr.map((a) => (a.type === type ? a : { ...a, visible: false }))
  const id = hidden.find((a) => a.type === type)?.id || anId()
  return upsertAnalysis(hidden, { id, type, visible: true, params })
}
// 碰撞安全组件 id：现存组件【最大数字后缀 +1】（+offset 供同批多件递增）。length-based 'C'+(len+1)
// 删组件后数组缩短而唔重编号 → 会重铸已存在 id（例 [C1,C2,C3] 删 C2 → [C1,C3]，'C'+(2+1)='C3' 撞）。
function nextCid(comps: { id: string }[], offset = 0): string {
  const maxN = comps.reduce((m, c) => { const n = parseInt(String(c.id).replace(/^C/, ''), 10); return Number.isFinite(n) && n > m ? n : m }, 0)
  return 'C' + (maxN + 1 + offset)
}
// R2 occurrence 纯逻辑核（nextDefId/reconcileComponents/migrateComponentDefs/makeDefOcc/cloneDef/writeDefFromEdit）
// 已抽去 ./assembly/occurrence.ts（单一真相 + tsx 可测），此处只留 store 专用嘅 detach 常量。
// 网格变异操作（scale/weld/simplify/boolean/convert/separate…）烘焙后 detach：断开与共享定义嘅链接，
// 令 reconcile 唔会反向覆盖新几何（呢批 op 语义 = 只影响此实例，独立化）。
const DETACH_DEF = { defId: undefined as string | undefined, _rev: undefined as number | undefined }
// R2 data-safety：回收孤儿 def（referencedDefs）+ 存档剥 occ.mesh（prunedDefsForPayload）—— 纯逻辑喺 ./assembly/occurrence.ts（tsx 可测）。
// R2：阵列（线性/环形/网格）+ 组复制 —— 每个副本要【独立 def】(cloneDef)，保 pre-R2 独立语义（编辑一件唔改全部）。
// duplicateComponent 共享 def 系 R2 设计（保留）；阵列/组应独立。返回要覆盖到 occurrence 上嘅 def 字段（并把新 def push 落 newDefs）；
// src 无 defId（匿名件）或 def 缺失 → 返 null（副本沿用 spread 后嘅原值 = 独立平铺副本，旧行为）。
function arrayCloneDefFor(src: { defId?: string }, allDefs: readonly StoreCompDef[], newDefs: StoreCompDef[]): { defId: string; _rev: number; mesh: MeshData } | null {
  if (!src.defId) return null
  const srcDef = allDefs.find((d) => d.id === src.defId)
  if (!srcDef) return null
  const nd = cloneDef([...allDefs, ...newDefs], srcDef)   // growing list → 同批多副本 def id 唔互撞
  newDefs.push(nd)
  return { defId: nd.id, _rev: 0, mesh: nd.mesh }
}
