  applyMirrorFacePick: (threePt: [number, number, number], faceNormal: [number, number, number]) => void
  controlNet: { nu: number; nv: number; poles: [number, number, number][]; nFaces?: number } | null   // S133：当前编辑曲面嘅控制网（loadControlNet 填）；nFaces（S133+多面）= 该壳总面数，供「面 1/N」循环
  loadControlNet: (target: number, face?: number) => Promise<void>                    // S133：读 parked 曲面 #target 第 face 张面控制网入 state（getControlNet）；face 缺省 0
  editPolesCommit: (target: number, face: number, deltas: [number, number, number][]) => Promise<void>  // S133：落 editpoles 特征 → applyFeatures 重建（face = 编辑哪张面）
  // S133 UI（sub-slice 2）：曲面极点编辑交互态 —— 拣 parked 曲面 → 显示控制点球 → 拖极点变形
  editPolesMode: boolean                                  // 编辑曲面控制点模式（ParkedBody 变可拾，PoleNet 显示极点球）
  editPolesTarget: number | null                          // 当前编辑嘅 parked 曲面索引（pickParkedForPoles 设）
  editPolesFace: number | null                            // S133+（多面）：当前编辑嘅 B-rep 面索引（缺省 0；cycleEditPolesFace 循环）
  editPolesDeltas: [number, number, number][] | null      // 逐极点累积世界偏移（row-major，长 nu*nv；拖极点累加）
  toggleEditPoles: () => void                             // 开/关编辑模式（关时清 target/face/controlNet/deltas）
  pickParkedForPoles: (idx: number, face?: number) => Promise<void>      // 拣 parked 曲面 #idx 第 face 张面 → loadControlNet + 初始化 deltas 为 0
  cycleEditPolesFace: () => Promise<void>                 // S133+（多面）：循环到下一张面（重读该面网 + 重置 deltas）
  moveEditPole: (poleIndex: number, worldDelta: [number, number, number]) => Promise<void>  // 累加该极点世界偏移入 deltas → editPolesCommit 重建变形
  startNewBody: () => Promise<void>                                       // 多实体：泊车当前实体开新（T728）
  commitBodyBoolean: (bop: 'fuse' | 'cut' | 'common', target: number) => Promise<void>  // 活动实体 ⊗ 泊车实体（B-rep）
