  toggleMeasureEdge: () => void
  measureEdgeAt: (threePt: [number, number, number]) => Promise<void>
  measureMeshEdgeAt: (compId: string, faceIndex: number, localPt: [number, number, number]) => void  // GM-W4 4.4(a)：网格件量边（特征棱链近似）
  measureFaceMode: boolean
  measureFaceInfo: string | null
  toggleMeasureFace: () => void
