  exportThreeMF: () => void
  exportStep: () => Promise<void>
  exportAssemblyStl: (union?: boolean) => void   // GM-W4 4.4(b)：union=真 CSG 布尔合并单壳（慢，打印更稳）；默认三角汤（快）
  exportAssemblyObj: () => void
  exportAssemblyThreeMF: () => void
