  if (p.kind === 'ellipse') { const out: Pt[] = []; for (let i = 0; i < 32; i++) { const a = (i * 2 * Math.PI) / 32; out.push([p.c[0] + p.rx * Math.cos(a), p.c[1] + p.ry * Math.sin(a)]) } return out }
