      if (r < 0.1) return { status: 'offset 太负，圆会消失 — 减小内缩量' }
      return { sketchUndo: [...s.sketchUndo, skSnap(s)].slice(-80), sketchRedo: [], sketchShape: { type: 'circle', c: base.c, r }, sketchProfiles: [], status: `已 offset 圆 Ø${(r * 2).toFixed(1)}` }
