        if (!s.sketchStart) return { sketchStart: pt, sketchPreview: pt, status: '中心矩形：再点一个角点（关于中心对称）' }
        const c = s.sketchStart
        const a: Pt = [2 * c[0] - pt[0], 2 * c[1] - pt[1]]
