        const centre: Pt = [mid[0] - side * (-dy / chord) * h, mid[1] - side * (dx / chord) * h]
        const norm = (x: number) => { let v = x; while (v < 0) v += 2 * Math.PI; while (v >= 2 * Math.PI) v -= 2 * Math.PI; return v }
        const a0 = Math.atan2(a[1] - old.c[1], a[0] - old.c[0]), a1 = Math.atan2(b[1] - old.c[1], b[0] - old.c[0]), am = Math.atan2(m[1] - old.c[1], m[0] - old.c[0])
        const span = norm(a1 - a0), sweep = norm(am - a0) <= span ? span : span - 2 * Math.PI
