          const y: [number, number, number] = [base.n[1] * base.xd[2] - base.n[2] * base.xd[1], base.n[2] * base.xd[0] - base.n[0] * base.xd[2], base.n[0] * base.xd[1] - base.n[1] * base.xd[0]]
