      const iCls = (typeof p.cls === 'string' && p.cls.trim()) ? p.cls : undefined
      const iStd = (typeof p.standard === 'string' && p.standard && p.standard !== 'iso') ? p.standard : undefined
      const iZ0 = Math.max(0, +(p.z0 || 0)) + iToff
