        set({ featDlg: null })
        await get().editFeature(d.editId, { d: dd, pitch: pp2, height: hh, x: +(p.x || 0), y: +(p.y || 0), z0: iZ0 || undefined, cosmetic: +(p.modeled || 0) ? undefined : true, lefthand: +(p.lefthand || 0) ? true : undefined, cls: iCls, standard: iStd })
