      const ek = r.radius != null ? (r.closed ? '圆棱' : '弧棱') : '直棱'
      const text = r.radius != null ? `${ek} Ø${fmtLen(r.radius * 2, u)} R${fmtLen(r.radius, u)} ${r.closed ? '周长' : '弧长'} ${fmtLen(r.length, u)}${fit}` : `直棱 长 ${fmtLen(r.length, u)}`
