      const feats: Feature[] = [
        { id: e, type: 'extrude', profile: { kind: 'poly', pts: [[0, 0], [70, 0], [70, 8], [8, 8], [8, 50], [0, 50]] as [number, number][] }, height: 40, operation: 'new', plane: 'XZ' },
      ]
